# owner: platform
"""Lay students out in seat order, one text line per row."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

# ---
def check_seats(seats_per_row: int) -> None:
    """Refuse a seat count that cannot make a row."""
    if seats_per_row <= 0:
        raise ValueError(
            f"seats must be positive, got {seats_per_row}"
        )

# ---
def seat_order(student: Student) -> Tuple[str, str]:
    """Last name first, then first name, ignoring case."""
    last = student.last_name.casefold()
    first = student.first_name.casefold()
    return (last, first)

# ---
def sorted_roster(
    students: Iterable[Student]
) -> List[Student]:
    """Students in seat order, refusing an empty list."""
    roster = sorted(students, key=seat_order)
    if not roster:
        raise ValueError("no students to seat")
    return roster

# ---
def chunk_roster(
    roster: List[Student], size: int
) -> List[List[Student]]:
    """Split the roster into groups of at most size."""
    starts = range(0, len(roster), size)
    return [roster[begin:begin + size] for begin in starts]

# ---
def format_seat_row(
    number: int, group: List[Student]
) -> str:
    """Text for one row, with bars between seats."""
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"

# ---
def format_rows(chunks: List[List[Student]]) -> List[str]:
    """Number each group and turn it into a row."""
    return [
        format_seat_row(number, group)
        for number, group in enumerate(chunks, start=1)
    ]

# ---
def seating_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    check_seats(seats_per_row)
    roster = sorted_roster(students)
    return format_rows(chunk_roster(roster, seats_per_row))

