# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows, sorted_roster

# ---
def make_student(
    last_name: str, first_name: str
) -> Student:
    """A section A student. Seating ignores the id."""
    return Student("0", last_name, first_name, "A")

ROSTER = [
    make_student("Halloway", "Juno"),
    make_student("Dunmere", "Piet"),
    make_student("Varrow", "Ines")
]

class SeatingTests(unittest.TestCase):
    def test_row_text_matches_the_example(self):
        rows = seating_rows(ROSTER[:2], 2)
        self.assertEqual(
            rows, ["Row 1: Dunmere, Piet | Halloway, Juno"]
        )

    def test_last_row_may_be_short(self):
        rows = seating_rows(ROSTER, 2)
        self.assertEqual(rows[1], "Row 2: Varrow, Ines")

    def test_students_sorted_by_last_name(self):
        ordered = sorted_roster(ROSTER)
        names = [item.last_name for item in ordered]
        self.assertEqual(
            names, ["Dunmere", "Halloway", "Varrow"]
        )

    def test_same_last_name_sorted_by_first_name(self):
        dunmere_piet = make_student("Dunmere", "Piet")
        dunmere_ada = make_student("Dunmere", "Ada")
        rows = seating_rows([dunmere_piet, dunmere_ada], 1)
        self.assertEqual(rows[0], "Row 1: Dunmere, Ada")

    def test_last_names_ignore_case(self):
        varrow = make_student("Varrow", "Ines")
        lower = make_student("dunmere", "Piet")
        rows = seating_rows([varrow, lower], 1)
        self.assertEqual(rows[0], "Row 1: dunmere, Piet")

    def test_seat_count_larger_than_class(self):
        rows = seating_rows(ROSTER, 10)
        self.assertEqual(len(rows), 1)

    def test_zero_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows(ROSTER, 0)

    def test_negative_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows(ROSTER, -3)

    def test_no_students_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
